<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\AuditLog;use App\Models\BusinessSetting;use App\Models\Notification;use App\Models\User;use App\Services\AlertService;use App\Support\BusinessAccess;use Illuminate\Http\Request;
class SettingsController extends Controller{
 public function settings(Request $r){return response()->json(['data'=>BusinessSetting::where('business_id',BusinessAccess::id($r))->pluck('value','key')]);}
 public function saveSettings(Request $r){BusinessAccess::requireRole($r,['owner','super_admin']);$data=$r->validate(['settings'=>['required','array'],'settings.vat_rate'=>['nullable','numeric','min:0','max:100'],'settings.invoice_prefix'=>['nullable','string','max:20'],'settings.payment_methods'=>['nullable','array']]);$business=BusinessAccess::id($r);foreach($data['settings'] as $key=>$value)BusinessSetting::updateOrCreate(['business_id'=>$business,'key'=>$key],['value'=>is_array($value)?json_encode($value):(string)$value]);$this->log($r,'settings.updated');return response()->json(['data'=>BusinessSetting::where('business_id',$business)->pluck('value','key')]);}
 public function users(Request $r){BusinessAccess::requireRole($r,['owner','manager','super_admin']);return response()->json(['data'=>User::where('business_id',BusinessAccess::id($r))->with('branch:id,name')->orderBy('name')->get()]);}
 public function storeUser(Request $r){BusinessAccess::requireRole($r,['owner','super_admin']);$business=BusinessAccess::id($r);$data=$r->validate(['name'=>['required','string','max:120'],'email'=>['required','email','max:120','unique:users,email'],'mobile'=>['nullable','string','max:20','unique:users,mobile'],'password'=>['required','string','min:8'],'role'=>['required','in:owner,manager,accountant,salesperson'],'branch_id'=>['nullable','integer','exists:branches,id']]);if(!empty($data['branch_id']))BusinessAccess::branch($r,$data['branch_id']);$user=User::create([...$data,'business_id'=>$business,'is_active'=>true]);$this->log($r,'user.created',User::class,$user->id);return response()->json(['data'=>$user->load('branch')],201);}
 public function updateUser(Request $r,User $user){BusinessAccess::requireRole($r,['owner','super_admin']);abort_unless($user->business_id===BusinessAccess::id($r),403);$data=$r->validate(['role'=>['sometimes','in:owner,manager,accountant,salesperson'],'branch_id'=>['nullable','integer','exists:branches,id'],'name'=>['sometimes','string','max:120'],'mobile'=>['nullable','string','max:20','unique:users,mobile,'.$user->id],'password'=>['nullable','string','min:8'],'is_active'=>['sometimes','boolean']]);if(!empty($data['branch_id']))BusinessAccess::branch($r,$data['branch_id']);if(array_key_exists('is_active',$data)&&!$data['is_active'])abort_if($user->is($r->user()),422,'You cannot deactivate your own account.');if(($data['role']??$user->role)!=='owner'&&$user->role==='owner')abort_if(User::where('business_id',$user->business_id)->where('role','owner')->where('is_active',true)->count()<=1,422,'The business must have at least one active owner.');$user->update($data);if(array_key_exists('role',$data)||array_key_exists('is_active',$data)||array_key_exists('password',$data))$user->tokens()->delete();$this->log($r,'user.updated',User::class,$user->id);return response()->json(['data'=>$user->fresh('branch')]);}
 public function notifications(Request $r,AlertService $alerts){$business=BusinessAccess::id($r);$alerts->generateForBusiness($business);return response()->json(['data'=>Notification::where('business_id',$business)->latest()->paginate($r->integer('per_page',30))]);}
 public function readNotification(Request $r,Notification $notification){abort_unless($notification->business_id===BusinessAccess::id($r),403);$notification->update(['read_at'=>now()]);return response()->json(['data'=>$notification]);}
 public function audit(Request $r){BusinessAccess::requireRole($r,['owner','manager','super_admin']);return response()->json(['data'=>AuditLog::where('business_id',BusinessAccess::id($r))->with('user:id,name')->latest()->paginate($r->integer('per_page',50))]);}
 private function log(Request $r,string $event,?string $type=null,?int $id=null):void{AuditLog::create(['business_id'=>$r->user()->business_id,'user_id'=>$r->user()->id,'event'=>$event,'subject_type'=>$type,'subject_id'=>$id,'ip_address'=>$r->ip()]);}
}
